character. NOTE: Annotation values must be 255 characters or less. Annotations can be added or modified at any time. Each resource can have multiple annota- tions. key -&gt; (string) value -&gt; (string) namespace -&gt; (string) The namespace of the Amazon EKS cluster. In Ku- bernetes, namespaces provide a mechanism for isolating groups of resources within a single cluster. Names of resources need to be unique within a namespace, but not across namespaces. Batch places Batch Job pods in this namespace. If this field is provided, the value can't be empty or null. It must meet the following re- quirements: o 1-63 characters long o Can't be set to default o Can't start with kube o Must match the following regular expression: ^[a-z0-9]([-a-z0-9]*[a-z0-9])?$ For more information, see Namespaces in the Ku- bernetes documentation . This namespace can be different from the kubernetesNamespace set in the compute environment's EksConfiguration , but must have identical role-based access con- trol (RBAC) roles as the compute environment's kubernetesNamespace . For multi-node parallel jobs, the same value must be provided across all the node ranges. shareProcessNamespace -&gt; (boolean) Indicates if the processes in a container are shared, or visible, to other containers in the same pod. For more information, see Share Process Namespace between Containers in a Pod . consumableResourceProperties -&gt; (structure) Contains a list of consumable resources required by a job. consumableResourceList -&gt; (list) The list of consumable resources required by a job. (structure) Information about a consumable resource required to run a job. consumableResource -&gt; (string) The name or ARN of the consumable resource. quantity -&gt; (long) The quantity of the consumable resource that is needed. JSON Syntax: { "numNodes": integer, "mainNode": integer, "nodeRangeProperties": [ { "targetNodes": "string", "container": { "image": "string", "vcpus": integer, "memory": integer, "command": ["string", ...], "jobRoleArn": "string", "executionRoleArn": "string", "volumes": [ { "host": { "sourcePath": "string" }, "name": "string", "efsVolumeConfiguration": { "fileSystemId": "string", "rootDirectory": "string", "transitEncryption": "ENABLED"|"DISABLED", "transitEncryptionPort": integer, "authorizationConfig": { "accessPointId": "string", "iam": "ENABLED"|"DISABLED" } }, "s3filesVolumeConfiguration": { "fileSystemArn": "string", "rootDirectory": "string", "transitEncryptionPort": integer, "accessPointArn": "string" } } ... ], "environment": [ { "name": "string", "value": "string" } ... ], "mountPoints": [ { "containerPath": "string", "readOnly": true|false, "sourceVolume": "string" } ... ], "readonlyRootFilesystem": true|false, "privileged": true|false, "ulimits": [ { "hardLimit": integer, "name": "string", "softLimit": integer } ... ], "user": "string", "instanceType": "string", "resourceRequirements": [ { "value": "string", "type": "GPU"|"VCPU"|"MEMORY" } ... ], "linuxParameters": { "devices": [ { "hostPath": "string", "containerPath": "string", "permissions": ["READ"|"WRITE"|"MKNOD", ...] } ... ], "initProcessEnabled": true|false, "sharedMemorySize": integer, "tmpfs": [ { "containerPath": "string", "size": integer, "mountOptions": ["string", ...] } ... ], "maxSwap": integer, "swappiness": integer }, "logConfiguration": { "logDriver": "json-file"|"syslog"|"journald"|"gelf"|"fluentd"|"awslogs"|"splunk"|"awsfirelens", "options": {"string": "string" ...}, "secretOptions": [ { "name": "string", "valueFrom": "string" } ... ] }, "secrets": [ { "name": "string", "valueFrom": "string" } ... ], "networkConfiguration": { "assignPublicIp": "ENABLED"|"DISABLED" }, "fargatePlatformConfiguration": { "platformVersion": "string" }, "enableExecuteCommand": true|false, "ephemeralStorage": { "sizeInGiB": integer }, "runtimePlatform": { "operatingSystemFamily": "string", "cpuArchitecture": "string" }, "repositoryCredentials": { "credentialsParameter": "string" } }, "instanceTypes":