dOnly": true|false } } ... ], "metadata": { "labels": {"string": "string" ...}, "annotations": {"string": "string" ...}, "namespace": "string" }, "shareProcessNamespace": true|false } }, "consumableResourceProperties": { "consumableResourceList": [ { "consumableResource": "string", "quantity": long } ... ] } } ... ] }
