    /// <summary>
    /// The retry strategy to use for failed jobs that are submitted with this job definition. Any retry strategy that's specified during a SubmitJob operation overrides the retry strategy defined here. If a job is terminated due to a timeout, it isn't retried. attempts -&gt; (integer) The number of times to move a job to the RUNNABLE status. You can specify between 1 and 10 attempts. If the value of attempts is greater than one, the job is retried on failure the same num- ber of attempts as the value. evaluateOnExit -&gt; (list) Array of up to 5 objects that specify the conditions where jobs are retried or failed. If this parameter is specified, then the attempts parameter must also be specified. If none of the listed conditions match, then the job is retried. (structure) Specifies an array of up to 5 conditions to be met, and an action to take (RETRY or EXIT ) if all conditions are met. If none of the EvaluateOnExit conditions in a RetryStrategy match, then the job is retried. onStatusReason -&gt; (string) Contains a glob pattern to match against the StatusReason returned for a job. The pattern can contain up to 512 characters. It can contain letters, numbers, periods (.), colons (:), and white spaces (including spaces or tabs). It can optionally end with an asterisk (*) so that only the start of the string needs to be an exact match. onReason -&gt; (string) Contains a glob pattern to match against the Reason re- turned for a job. The pattern can contain up to 512 char- acters. It can contain letters, numbers, periods (.), colons (:), and white space (including spaces and tabs). It can optionally end with an asterisk (*) so that only the start of the string needs to be an exact match. onExitCode -&gt; (string) Contains a glob pattern to match against the decimal rep- resentation of the ExitCode returned for a job. The pat- tern can be up to 512 characters long. It can contain only numbers, and can end with an asterisk (*) so that only the start of the string needs to be an exact match. The string can contain up to 512 characters. action -&gt; (string) [required] Specifies the action to take if all of the specified con- ditions (onStatusReason , onReason , and onExitCode ) are met. The values aren't case sensitive. Possible values: o RETRY o EXIT Shorthand Syntax: attempts=integer,evaluateOnExit=[{onStatusReason=string,onReason=string,onExitCode=string,action=string},{onStatusReason=string,onReason=string,onExitCode=string,action=string}] JSON Syntax: { "attempts": integer, "evaluateOnExit": [ { "onStatusReason": "string", "onReason": "string", "onExitCode": "string", "action": "RETRY"|"EXIT" } ... ] }
    /// </summary>
    [CliOption("--retry-strategy")]
    public string? RetryStrategy { get; set; }

    /// <summary>
    /// Specifies whether to propagate the tags from the job or job defini- tion to the corresponding Amazon ECS task. If no value is specified, the tags are not propagated. Tags can only be propagated to the tasks during task creation. For tags with the same name, job tags are given priority over job definitions tags. If the total number of combined tags from the job and job definition is over 50, the job is moved to the FAILED state. NOTE: If the job runs on Amazon EKS resources, then you must not spec- ify propagateTags .
    /// </summary>
    [CliFlag("--propagate-tags", NegatedName = "--no-propagate-tags")]
    public bool? PropagateTags { get; set; }

    /// <summary>
    /// The timeout configuration for jobs that are submitted with this job definition, after which Batch terminates your jobs if they have not finished. If a job is terminated due to a timeout, it isn't retried. The minimum value for the timeout is 60 seconds. Any timeout config- uration that's specified during a SubmitJob operation overrides the timeout configuration defined here. For more information, see Job Timeouts in the Batch User Guide . attemptDurationSeconds -&gt; (integer) The job timeout time (in seconds) that's measured from the job attempt's startedAt timestamp. After this time passes, Batch terminates your jobs if they aren't finished. The minimum value for the timeout is 60 seconds. For array jobs, the timeout applies to the child jobs, not to the parent array job. For multi-node parallel (MNP) jobs, the timeout applies to the whole job, not to the individual nodes. Shorthand Syntax: attemptDurationSeconds=integer JSON Syntax: { "attemptDurationSeconds": integer }
    /// </summary>
    [CliOption("--timeout")]
    public string? Timeout { get; set; }

    /// <summary>
    /// The tags that you apply to the job definition to help you categorize and organize your resources. Each tag consists of a key and an op- tional value. For more information, see Tagging Amazon Web Services Resources in Batch User Guide . Constraints: o min: 1 o max: 50 key -&gt; (string) Constraints: o min: 1 o max: 128 value -&gt; (string) Constraints: o max: 256 Shorthand Syntax: KeyName1=string,KeyName2=string JSON Syntax: {"string": "string" ...}
    /// </summary>
    [CliOption("--tags", CollectionSeparator = ",")]
    public IReadOnlyList<KeyValue>? Tags { get; set; }

    /// <summary>
    /// The platform capabilities required by the job definition. If no value is specified, it defaults to EC2 . To run the job on Fargate resources, specify FARGATE . To run the job on Amazon ECS Managed Instances, specify MANAGED_INSTANCES . Jobs with the MANAGED_INSTANCES platform capability must use ec- sProperties (not containerProperties ) and do not support multi-node parallel jobs. NOTE: If the job runs on Amazon EKS resources, then you must not spec- ify platformCapabilities . (string) Possible values: o EC2 o FARGATE o MANAGED_INSTANCES Syntax: "string" "string" ...
    /// </summary>
    [CliOption("--platform-capabilities", GroupValues = true)]
    public IEnumerable<string>? PlatformCapabilities { get; set; }

    /// <summary>
    /// An object with properties that are specific to Amazon EKS-based jobs. This must not be specified for Amazon ECS based job defini- tions. podProperties -&gt; (structure) The properties for the Kubernetes pod resources of a job. serviceAccountName -&gt; (string) The name of the service account that's used to run the pod. For more information, see Kubernetes service accounts and Configure a Kubernetes service account to assume an IAM role in the Amazon EKS User Guide and Configure service accounts for pods in the Kubernetes documentation . hostNetwork -&gt; (boolean) Indicates if the pod uses the hosts' network IP address. The default value is true . Setting this to false enables the Ku- bernetes pod networking model. Most Batch workloads are egress-only and don't require the overhead of IP allocation for each pod for incoming connections. For more information, see Host namespaces and Pod networking in the Kubernetes doc- umentation . dnsPolicy -&gt; (string) The DNS policy for the pod. The default value is ClusterFirst . If the hostNetwork parameter is not specified, the default is ClusterFirstWithHostNet . ClusterFirst indicates that any DNS query that does not match the configured cluster domain suffix is forwarded to the upstream nameserver inherited from the node. For more information, see Pod's DNS policy in the Kubernetes documentation . Valid values: Default | ClusterFirst | ClusterFirstWithHost- Net imagePullSecrets -&gt; (list) References a Kubernetes secret resource. It holds a list of secrets. These secrets help to gain access to pull an images from a private registry. ImagePullSecret$name is required when this object is used. (structure) References a Kubernetes secret resource. This name of the secret must start and end with an alphanumeric character, is required to be lowercase, can include periods (.) and hyphens (-), and can't contain more than 253 characters. name -&gt; (string) [required] Provides a unique identifier for the ImagePullSecret . This object is required when EksPodProperties$im- agePullSecrets is used. containers -&gt; (list) The properties of the container that's used on the Amazon EKS pod. NOTE: This object is limited to 10 elements. (structure) EKS container properties are used in job definitions for Amazon EKS based job definitions to describe the proper- ties for a container node in the pod that's launched as part of a job. This can't be specified for Amazon ECS based job definitions. name -&gt; (string) The name of the container. If the name isn't speci- fied, the default name "Default " is used. Each con- tainer in a pod must have a unique name. image -&gt; (string) [required] The Docker image used to start the container. imagePullPolicy -&gt; (string) The image pull policy for the container. Supported values are Always , IfNotPresent , and Never . This parameter defaults to IfNotPresent . However, if the :latest tag is specified, it defaults to Always . For more information, see Updating images in the Kuber- netes documentation . command -&gt; (list) The entrypoint for the container. This isn't run within a shell. If this isn't specified, the ENTRY- POINT of the container image is used. Environment variable references are expanded using the container's environment. If the referenced environment variable doesn't exist, the reference in the command isn't changed. For exam- ple, if the reference is to "$(NAME1) " and the NAME1 environment variable doesn't exist, the command string will remain "$(NAME1) ." $$ is replaced with $ and the resulting string isn't expanded. For example, $$(VAR_NAME) will be passed as $(VAR_NAME) whether or not the VAR_NAME environment variable exists. The en- trypoint can't be updated. For more information, see ENTRYPOINT in the Dockerfile reference and Define a command and arguments for a container and Entrypoint in the Kubernetes documentation . (string) args -&gt; (list) An array of arguments to the entrypoint. If this isn't specified, the CMD of the container image is used. This corresponds to the args member in the Entrypoint portion of the Pod in Kubernetes. Environment variable references are expanded using the container's environ- ment. If the referenced environment variable doesn't exist, the reference in the command isn't changed. For exam- ple, if the reference is to "$(NAME1) " and the NAME1 environment variable doesn't exist, the command string will remain "$(NAME1) ." $$ is replaced with $ , and the resulting string isn't expanded. For example, $$(VAR_NAME) is passed as $(VAR_NAME) whether or not the VAR_NAME environment variable exists. For more in- formation, see Dockerfile reference: CMD and Define a command and arguments for a pod in the Kubernetes doc- umentation . (string) env -&gt; (list) The environment variables to pass to a container. NOTE: Environment variables cannot start with "AWS_BATCH ". This naming convention is reserved for vari- ables that Batch sets. (structure) An environment variable. name -&gt; (string) [required] The name of the environment variable. value -&gt; (string) The value of the environment variable. resources -&gt; (structure) The type and amount of resources to assign to a con- tainer. The supported resources include memory , cpu , and nvidia.com/gpu . For more information, see Resource management for pods and containers in the Ku- bernetes documentation . limits -&gt; (map) The type and quantity of the resources to reserve for the container. The values vary based on the name that's specified. Resources can be requested using either the limits or the requests objects. memory The memory hard limit (in MiB) for the container, using whole integers, with a "Mi" suffix. If your container attempts to exceed the memory specified, the container is terminated. You must specify at least 4 MiB of memory for a job. memory can be specified in limits , requests , or both. If mem- ory is specified in both places, then the value that's specified in limits must be equal to the value that's specified in requests . NOTE: To maximize your resource utilization, provide your jobs with as much memory as possible for the specific instance type that you are using. To learn how, see Memory management in the Batch User Guide . cpu The number of CPUs that's reserved for the con- tainer. Values must be an even multiple of 0.25 . cpu can be specified in limits , requests , or both. If cpu is specified in both places, then the value that's specified in limits must be at least as large as the value that's specified in requests . nvidia.com/gpu The number of GPUs that's reserved for the con- tainer. Values must be a whole integer. memory can be specified in limits , requests , or both. If memory is specified in both places, then the value that's specified in limits must be equal to the value that's specified in requests . key -&gt; (string) value -&gt; (string) Constraints: o min: 1 o max: 256 requests -&gt; (map) The type and quantity of the resources to request for the container. The values vary based on the name that's specified. Resources can be requested by using either the limits or the requests ob- jects. memory The memory hard limit (in MiB) for the container, using whole integers, with a "Mi" suffix. If your container attempts to exceed the memory specified, the container is terminated. You must specify at least 4 MiB of memory for a job. memory can be specified in limits , requests , or both. If mem- ory is specified in both, then the value that's specified in limits must be equal to the value that's specified in requests . NOTE: If you're trying to maximize your resource uti- lization by providing your jobs as much memory as possible for a particular instance type, see Memory management in the Batch User Guide . cpu The number of CPUs that are reserved for the con- tainer. Values must be an even multiple of 0.25 . cpu can be specified in limits , requests , or both. If cpu is specified in both, then the value that's specified in limits must be at least as large as the value that's specified in requests . nvidia.com/gpu The number of GPUs that are reserved for the con- tainer. Values must be a whole integer. nvidia.com/gpu can be specified in limits , re- quests , or both. If nvidia.com/gpu is specified in both, then the value that's specified in limits must be equal to the value that's specified in re- quests . key -&gt; (string) value -&gt; (string) Constraints: o min: 1 o max: 256 volumeMounts -&gt; (list) The volume mounts for the container. Batch supports emptyDir , hostPath , and secret volume types. For more information about volumes and volume mounts in Kubernetes, see Volumes in the Kubernetes documenta- tion . (structure) The volume mounts for a container for an Amazon EKS job. For more information about volumes and volume mounts in Kubernetes, see Volumes in the Kubernetes documentation . name -&gt; (string) The name the volume mount. This must match the name of one of the volumes in the pod. mountPath -&gt; (string) The path on the container where the volume is mounted. subPath -&gt; (string) A sub-path inside the referenced volume instead of its root. readOnly -&gt; (boolean) If this value is true , the container has read-only access to the volume. Otherwise, the container can write to the volume. The default value is false . securityContext -&gt; (structure) The security context for a job. For more information, see Configure a security context for a pod or con- tainer in the Kubernetes documentation . runAsUser -&gt; (long) When this parameter is specified, the container is run as the specified user ID (uid ). If this para- meter isn't specified, the default is the user that's specified in the image metadata. This para- meter maps to RunAsUser and MustRanAs policy in the Users and groups pod security policies in the Kubernetes documentation . runAsGroup -&gt; (long) When this parameter is specified, the container is run as the specified group ID (gid ). If this pa- rameter isn't specified, the default is the group that's specified in the image metadata. This para- meter maps to RunAsGroup and MustRunAs policy in the Users and groups pod security policies in the Kubernetes documentation . privileged -&gt; (boolean) When this parameter is true , the container is given elevated permissions on the host container instance. The level of permissions are similar to the root user permissions. The default value is false . This parameter maps to privileged policy in the Privileged pod security policies in the Ku- bernetes documentation . allowPrivilegeEscalation -&gt; (boolean) Whether or not a container or a Kubernetes pod is allowed to gain more privileges than its parent process. The default value is false . readOnlyRootFilesystem -&gt; (boolean) When this parameter is true , the container is given read-only access to its root file system. The default value is false . This parameter maps to ReadOnlyRootFilesystem policy in the Volumes and file systems pod security policies in the Ku- bernetes documentation . runAsNonRoot -&gt; (boolean) When this parameter is specified, the container is run as a user with a uid other than 0. If this pa- rameter isn't specified, so such rule is enforced. This parameter maps to RunAsUser and MustRunAsNon- Root policy in the Users and groups pod security policies in the Kubernetes documentation . initContainers -&gt; (list) These containers run before application containers, always runs to completion, and must complete successfully before the next container starts. These containers are registered with the Amazon EKS Connector agent and persists the registration information in the Kubernetes backend data store. For more information, see Init Containers in the Kubernetes documenta- tion . NOTE: This object is limited to 10 elements. (structure) EKS container properties are used in job definitions for Amazon EKS based job definitions to describe the proper- ties for a container node in the pod that's launched as part of a job. This can't be specified for Amazon ECS based job definitions. name -&gt; (string) The name of the container. If the name isn't speci- fied, the default name "Default " is used. Each con- tainer in a pod must have a unique name. image -&gt; (string) [required] The Docker image used to start the container. imagePullPolicy -&gt; (string) The image pull policy for the container. Supported values are Always , IfNotPresent , and Never . This parameter defaults to IfNotPresent . However, if the :latest tag is specified, it defaults to Always . For more information, see Updating images in the Kuber- netes documentation . command -&gt; (list) The entrypoint for the container. This isn't run within a shell. If this isn't specified, the ENTRY- POINT of the container image is used. Environment variable references are expanded using the container's environment. If the referenced environment variable doesn't exist, the reference in the command isn't changed. For exam- ple, if the reference is to "$(NAME1) " and the NAME1 environment variable doesn't exist, the command string will remain "$(NAME1) ." $$ is replaced with $ and the resulting string isn't expanded. For example, $$(VAR_NAME) will be passed as $(VAR_NAME) whether or not the VAR_NAME environment variable exists. The en- trypoint can't be updated. For more information, see ENTRYPOINT in the Dockerfile reference and Define a command and arguments for a container and Entrypoint in the Kubernetes documentation . (string) args -&gt; (list) An array of arguments to the entrypoint. If this isn't specified, the CMD of the container image is used. This corresponds to the args member in the Entrypoint portion of the Pod in Kubernetes. Environment variable references are expanded using the container's environ- ment. If the referenced environment variable doesn't exist, the reference in the command isn't changed. For exam- ple, if the reference is to "$(NAME1) " and the NAME1 environment variable doesn't exist, the command string will remain "$(NAME1) ." $$ is replaced with $ , and the resulting string isn't expanded. For example, $$(VAR_NAME) is passed as $(VAR_NAME) whether or not the VAR_NAME environment variable exists. For more in- formation, see Dockerfile reference: CMD and Define a command and arguments for a pod in the Kubernetes doc- umentation . (string) env -&gt; (list) The environment variables to pass to a container. NOTE: Environment variables cannot start with "AWS_BATCH ". This naming convention is reserved for vari- ables that Batch sets. (structure) An environment variable. name -&gt; (string) [required] The name of the environment variable. value -&gt; (string) The value of the environment variable. resources -&gt; (structure) The type and amount of resources to assign to a con- tainer. The supported resources include memory , cpu , and nvidia.com/gpu . For more information, see Resource management for pods and containers in the Ku- bernetes documentation . limits -&gt; (map) The type and quantity of the resources to reserve for the container. The values vary based on the name that's specified. Resources can be requested using either the limits or the requests objects. memory The memory hard limit (in MiB) for the container, using whole integers, with a "Mi" suffix. If your container attempts to exceed the memory specified, the container is terminated. You must specify at least 4 MiB of memory for a job. memory can be specified in limits , requests , or both. If mem- ory is specified in both places, then the value that's specified in limits must be equal to the value that's specified in requests . NOTE: To maximize your resource utilization, provide your jobs with as much memory as possible for the specific instance type that you are using. To learn how, see Memory management in the Batch User Guide . cpu The number of CPUs that's reserved for the con- tainer. Values must be an even multiple of 0.25 . cpu can be specified in limits , requests , or both. If cpu is specified in both places, then the value that's specified in limits must be at least as large as the value that's specified in requests . nvidia.com/gpu The number of GPUs that's reserved for the con- tainer. Values must be a whole integer. memory can be specified in limits , requests , or both. If memory is specified in both places, then the value that's specified in limits must be equal to the value that's specified in requests . key -&gt; (string) value -&gt; (string) Constraints: o min: 1 o max: 256 requests -&gt; (map) The type and quantity of the resources to request for the container. The values vary based on the name that's specified. Resources can be requested by using either the limits or the requests ob- jects. memory The memory hard limit (in MiB) for the container, using whole integers, with a "Mi" suffix. If your container attempts to exceed the memory specified, the container is terminated. You must specify at least 4 MiB of memory for a job. memory can be specified in limits , requests , or both. If mem- ory is specified in both, then the value that's specified in limits must be equal to the value that's specified in requests . NOTE: If you're trying to maximize your resource uti- lization by providing your jobs as much memory as possible for a particular instance type, see Memory management in the Batch User Guide . cpu The number of CPUs that are reserved for the con- tainer. Values must be an even multiple of 0.25 . cpu can be specified in limits , requests , or both. If cpu is specified in both, then the value that's specified in limits must be at least as large as the value that's specified in requests . nvidia.com/gpu The number of GPUs that are reserved for the con- tainer. Values must be a whole integer. nvidia.com/gpu can be specified in limits , re- quests , or both. If nvidia.com/gpu is specified in both, then the value that's specified in limits must be equal to the value that's specified in re- quests . key -&gt; (string) value -&gt; (string) Constraints: o min: 1 o max: 256 volumeMounts -&gt; (list) The volume mounts for the container. Batch supports emptyDir , hostPath , and secret volume types. For more information about volumes and volume mounts in Kubernetes, see Volumes in the Kubernetes documenta- tion . (structure) The volume mounts for a container for an Amazon EKS job. For more information about volumes and volume mounts in Kubernetes, see Volumes in the Kubernetes documentation . name -&gt; (string) The name the volume mount. This must match the name of one of the volumes in the pod. mountPath -&gt; (string) The path on the container where the volume is mounted. subPath -&gt; (string) A sub-path inside the referenced volume instead of its root. readOnly -&gt; (boolean) If this value is true , the container has read-only access to the volume. Otherwise, the container can write to the volume. The default value is false . securityContext -&gt; (structure) The security context for a job. For more information, see Configure a security context for a pod or con- tainer in the Kubernetes documentation . runAsUser -&gt; (long) When this parameter is specified, the container is run as the specified user ID (uid ). If this para- meter isn't specified, the default is the user that's specified in the image metadata. This para- meter maps to RunAsUser and MustRanAs policy in the Users and groups pod security policies in the Kubernetes documentation . runAsGroup -&gt; (long) When this parameter is specified, the container is run as the specified group ID (gid ). If this pa- rameter isn't specified, the default is the group that's specified in the image metadata. This para- meter maps to RunAsGroup and MustRunAs policy in the Users and groups pod security policies in the Kubernetes documentation . privileged -&gt; (boolean) When this parameter is true , the container is given elevated permissions on the host container instance. The level of permissions are similar to the root user permissions. The default value is false . This parameter maps to privileged policy in the Privileged pod security policies in the Ku- bernetes documentation . allowPrivilegeEscalation -&gt; (boolean) Whether or not a container or a Kubernetes pod is allowed to gain more privileges than its parent process. The default value is false . readOnlyRootFilesystem -&gt; (boolean) When this parameter is true , the container is given read-only access to its root file system. The default value is false . This parameter maps to ReadOnlyRootFilesystem policy in the Volumes and file systems pod security policies in the Ku- bernetes documentation . runAsNonRoot -&gt; (boolean) When this parameter is specified, the container is run as a user with a uid other than 0. If this pa- rameter isn't specified, so such rule is enforced. This parameter maps to RunAsUser and MustRunAsNon- Root policy in the Users and groups pod security policies in the Kubernetes documentation . volumes -&gt; (list) Specifies the volumes for a job definition that uses Amazon EKS resources. (structure) Specifies an Amazon EKS volume for a job definition. name -&gt; (string) [required] The name of the volume. The name must be allowed as a DNS subdomain name. For more information, see DNS sub- domain names in the Kubernetes documentation . hostPath -&gt; (structure) Specifies the configuration of a Kubernetes hostPath volume. For more information, see hostPath in the Ku- bernetes documentation . path -&gt; (string) The path of the file or directory on the host to mount into containers on the pod. emptyDir -&gt; (structure) Specifies the configuration of a Kubernetes emptyDir volume. For more information, see emptyDir in the Ku- bernetes documentation . medium -&gt; (string) The medium to store the volume. The default value is an empty string, which uses the storage of the node. "" (Default) Use the disk storage of the node. "Memory" Use the tmpfs volume that's backed by the RAM of the node. Contents of the volume are lost when the node reboots, and any storage on the volume counts against the container's memory limit. sizeLimit -&gt; (string) The maximum size of the volume. By default, there's no maximum size defined. Constraints: o min: 1 o max: 256 secret -&gt; (structure) Specifies the configuration of a Kubernetes secret volume. For more information, see secret in the Kuber- netes documentation . secretName -&gt; (string) [required] The name of the secret. The name must be allowed as a DNS subdomain name. For more information, see DNS subdomain names in the Kubernetes documenta- tion . optional -&gt; (boolean) Specifies whether the secret or the secret's keys must be defined. persistentVolumeClaim -&gt; (structure) Specifies the configuration of a Kubernetes persis- tentVolumeClaim bounded to a persistentVolume . For more information, see Persistent Volume Claims in the Kubernetes documentation . claimName -&gt; (string) [required] The name of the persistentVolumeClaim bounded to a persistentVolume . For more information, see Persistent Volume Claims in the Kubernetes docu- mentation . readOnly -&gt; (boolean) An optional boolean value indicating if the mount is read only. Default is false. For more informa- tion, see Read Only Mounts in the Kubernetes docu- mentation . metadata -&gt; (structure) Metadata about the Kubernetes pod. For more information, see Understanding Kubernetes Objects in the Kubernetes documenta- tion . labels -&gt; (map) Key-value pairs used to identify, sort, and organize cube resources. Can contain up to 63 uppercase letters, lower- case letters, numbers, hyphens (-), and underscores (_). Labels can be added or modified at any time. Each re- source can have multiple labels, but each key must be unique for a given object. key -&gt; (string) value -&gt; (string) annotations -&gt; (map) Key-value pairs used to attach arbitrary, non-identifying metadata to Kubernetes objects. Valid annotation keys have two segments: an optional prefix and a name, sepa- rated by a slash (/). o The prefix is optional and must be 253 characters or less. If specified, the prefix must be a DNS subdomain a series of DNS labels separated by dots (.), and it must end with a slash (/). o The name segment is required and must be 63 characters or less. It can include alphanumeric characters ([a-z0-9A-Z]), dashes (-), underscores (_), and dots (.), but must begin and end with an alphanumeric char- acter. NOTE: Annotation values must be 255 characters or less. Annotations can be added or modified at any time. Each resource can have multiple annotations. key -&gt; (string) value -&gt; (string) namespace -&gt; (string) The namespace of the Amazon EKS cluster. In Kubernetes, namespaces provide a mechanism for isolating groups of resources within a single cluster. Names of resources need to be unique within a namespace, but not across namespaces. Batch places Batch Job pods in this name- space. If this field is provided, the value can't be empty or null. It must meet the following requirements: o 1-63 characters long o Can't be set to default o Can't start with kube o Must match the following regular expression: ^[a-z0-9]([-a-z0-9]*[a-z0-9])?$ For more information, see Namespaces in the Kubernetes documentation . This namespace can be different from the kubernetesNamespace set in the compute environment's EksConfiguration , but must have identical role-based ac- cess control (RBAC) roles as the compute environment's kubernetesNamespace . For multi-node parallel jobs, the same value must be provided across all the node ranges. shareProcessNamespace -&gt; (boolean) Indicates if the processes in a container are shared, or vis- ible, to other containers in the same pod. For more informa- tion, see Share Process Namespace between Containers in a Pod . JSON Syntax: { "podProperties": { "serviceAccountName": "string", "hostNetwork": true|false, "dnsPolicy": "string", "imagePullSecrets": [ { "name": "string" } ... ], "containers": [ { "name": "string", "image": "string", "imagePullPolicy": "string", "command": ["string", ...], "args": ["string", ...], "env": [ { "name": "string", "value": "string" } ... ], "resources": { "limits": {"string": "string" ...}, "requests": {"string": "string" ...} }, "volumeMounts": [ { "name": "string", "mountPath": "string", "subPath": "string", "readOnly": true|false } ... ], "securityContext": { "runAsUser": long, "runAsGroup": long, "privileged": true|false, "allowPrivilegeEscalation": true|false, "readOnlyRootFilesystem": true|false, "runAsNonRoot": true|false } } ... ], "initContainers": [ { "name": "string", "image": "string", "imagePullPolicy": "string", "command": ["string", ...], "args": ["string", ...], "env": [ { "name": "string", "value": "string" } ... ], "resources": { "limits": {"string": "string" ...}, "requests": {"string": "string" ...} }, "volumeMounts": [ { "name": "string", "mountPath": "string", "subPath": "string", "readOnly": true|false } ... ], "securityContext": { "runAsUser": long, "runAsGroup": long, "privileged": true|false, "allowPrivilegeEscalation": true|false, "readOnlyRootFilesystem": true|false, "runAsNonRoot": true|false } } ... ], "volumes": [ { "name": "string", "hostPath": { "path": "string" }, "emptyDir": { "medium": "string", "sizeLimit": "string" }, "secret": { "secretName": "string", "optional": true|false }, "persistentVolumeClaim": { "claimName": "string", "readOnly": true|false } } ... ], "metadata": { "labels": {"string": "string" ...}, "annotations": {"string": "string" ...}, "namespace": "string" }, "shareProcessNamespace": true|false } }
    /// </summary>
    [CliOption("--eks-properties")]
    public string? EksProperties { get; set; }

    /// <summary>
    /// An object with properties that are specific to Amazon ECS-based jobs. This must not be specified for Amazon EKS-based job defini- tions. taskProperties -&gt; (list) [required] An object that contains the properties for the Amazon ECS task definition of a job. NOTE: This object is currently limited to one task element. How- ever, the task element can run up to 10 containers. (structure) The properties for a task definition that describes the con- tainer and volume definitions of an Amazon ECS task. You can specify which Docker images to use, the required resources, and other configurations related to launching the task defin- ition through an Amazon ECS service or task. containers -&gt; (list) [required] This object is a list of containers. (structure) Container properties are used for Amazon ECS-based job definitions. These properties to describe the con- tainer that's launched as part of a job. command -&gt; (list) The command that's passed to the container. This parameter maps to Cmd in the Create a container section of the Docker Remote API and the COMMAND parameter to docker run . For more information, see Dockerfile reference: CMD . (string) dependsOn -&gt; (list) A list of containers that this container depends on. (structure) A list of containers that this task depends on. containerName -&gt; (string) A unique identifier for the container. condition -&gt; (string) The dependency condition of the container. The following are the available conditions and their behavior: o START - This condition emulates the be- havior of links and volumes today. It validates that a dependent container is started before permitting other contain- ers to start. o COMPLETE - This condition validates that a dependent container runs to completion (exits) before permitting other contain- ers to start. This can be useful for nonessential containers that run a script and then exit. This condition can't be set on an essential container. o SUCCESS - This condition is the same as COMPLETE , but it also requires that the container exits with a zero status. This condition can't be set on an essential container. environment -&gt; (list) The environment variables to pass to a container. This parameter maps to Env in the Create a con- tainer section of the Docker Remote API and the --env parameter to docker run . WARNING: We don't recommend using plaintext environment variables for sensitive information, such as credential data. NOTE: Environment variables cannot start with AWS_BATCH . This naming convention is reserved for variables that Batch sets. (structure) A key-value pair object. name -&gt; (string) The name of the key-value pair. For envi- ronment variables, this is the name of the environment variable. value -&gt; (string) The value of the key-value pair. For envi- ronment variables, this is the value of the environment variable. essential -&gt; (boolean) If the essential parameter of a container is marked as true , and that container fails or stops for any reason, all other containers that are part of the task are stopped. If the essential parame- ter of a container is marked as false, its failure doesn't affect the rest of the containers in a task. If this parameter is omitted, a container is assumed to be essential. All jobs must have at least one essential con- tainer. If you have an application that's composed of multiple containers, group containers that are used for a common purpose into components, and separate the different components into multiple task definitions. For more information, see Application Architecture in the Amazon Elastic Container Service Developer Guide . firelensConfiguration -&gt; (structure) The FireLens configuration for the container. This is used to specify and configure a log router for container logs. For more information, see Custom log routing in the Amazon Elastic Container Ser- vice Developer Guide . type -&gt; (string) [required] The log router to use. The valid values are fluentd or fluentbit . Possible values: o fluentd o fluentbit options -&gt; (map) The options to use when configuring the log router. This field is optional and can be used to specify a custom configuration file or to add additional metadata, such as the task, task definition, cluster, and container instance de- tails to the log event. If specified, the syn- tax to use is "options":{"enable-ecs-log-meta- data":"true|false","con- fig-file-type:"s3|file","con- fig-file-value":"arn:aws:s3:::mybucket/flu- ent.conf|filepath"} . For more information, see Creating a task definition that uses a FireLens configuration in the Amazon Elastic Container Service Developer Guide . key -&gt; (string) value -&gt; (string) image -&gt; (string) [required] The image used to start a container. This string is passed directly to the Docker daemon. By de- fault, images in the Docker Hub registry are available. Other repositories are specified with either repository-url/image:tag or reposi- tory-url/image@digest . Up to 255 letters (upper- case and lowercase), numbers, hyphens, under- scores, colons, periods, forward slashes, and num- ber signs are allowed. This parameter maps to Im- age in the Create a container section of the Docker Remote API and the IMAGE parameter of the ` docker run https://docs.docker.com/engine/reference/run/#security-configuration`__ . linuxParameters -&gt; (structure) Linux-specific modifications that are applied to the container, such as Linux kernel capabilities. For more information, see KernelCapabilities . devices -&gt; (list) Any of the host devices to expose to the con- tainer. This parameter maps to Devices in the Create a container section of the Docker Remote API and the --device option to docker run . NOTE: This parameter isn't applicable to jobs that are running on Fargate resources. Don't provide it for these jobs. (structure) An object that represents a container in- stance host device. NOTE: This object isn't applicable to jobs that are running on Fargate resources and shouldn't be provided. hostPath -&gt; (string) [required] The path for the device on the host con- tainer instance. containerPath -&gt; (string) The path inside the container that's used to expose the host device. By de- fault, the hostPath value is used. permissions -&gt; (list) The explicit permissions to provide to the container for the device. By de- fault, the container has permissions for read , write , and mknod for the device. (string) Possible values: o READ o WRITE o MKNOD initProcessEnabled -&gt; (boolean) If true, run an init process inside the con- tainer that forwards signals and reaps processes. This parameter maps to the --init option to docker run . This parameter requires version 1.25 of the Docker Remote API or greater on your container instance. To check the Docker Remote API version on your container instance, log in to your container instance and run the following command: sudo docker version | grep "Server API version" sharedMemorySize -&gt; (integer) The value for the size (in MiB) of the /dev/shm volume. This parameter maps to the --shm-size option to docker run . NOTE: This parameter isn't applicable to jobs that are running on Fargate resources. Don't provide it for these jobs. tmpfs -&gt; (list) The container path, mount options, and size (in MiB) of the tmpfs mount. This parameter maps to the --tmpfs option to docker run . NOTE: This parameter isn't applicable to jobs that are running on Fargate resources. Don't provide this parameter for this re- source type. (structure) The container path, mount options, and size of the tmpfs mount. NOTE: This object isn't applicable to jobs that are running on Fargate resources. containerPath -&gt; (string) [required] The absolute file path in the container where the tmpfs volume is mounted. size -&gt; (integer) [required] The size (in MiB) of the tmpfs volume. mountOptions -&gt; (list) The list of tmpfs volume mount options. Valid values: "defaults " | "ro " | "rw " | "suid " | "nosuid " | "dev " | "nodev " | "exec " | "noexec " | "sync " | "async " | "dirsync " | "remount " | "mand " | "nomand " | "atime " | "noat- ime " | "diratime " | "nodiratime " | "bind " | "rbind" | "unbindable" | "run- bindable" | "private" | "rprivate" | "shared" | "rshared" | "slave" | "rslave" | "relatime " | "norelatime " | "strictatime " | "nostrictatime " | "mode " | "uid " | "gid " | "nr_inodes " | "nr_blocks " | "mpol " (string) maxSwap -&gt; (integer) The total amount of swap memory (in MiB) a con- tainer can use. This parameter is translated to the --memory-swap option to docker run where the value is the sum of the container memory plus the maxSwap value. For more information, see ` --memory-swap details &lt;- https://docs.docker.com/config/containers/re- source_constraints/#--memory-swap-details&gt;`__ in the Docker documentation. If a maxSwap value of 0 is specified, the con- tainer doesn't use swap. Accepted values are 0 or any positive integer. If the maxSwap parame- ter is omitted, the container doesn't use the swap configuration for the container instance on which it runs. A maxSwap value must be set for the swappiness parameter to be used. NOTE: This parameter isn't applicable to jobs that are running on Fargate resources. Don't provide it for these jobs. swappiness -&gt; (integer) You can use this parameter to tune a con- tainer's memory swappiness behavior. A swappi- ness value of 0 causes swapping to not occur unless absolutely necessary. A swappiness value of 100 causes pages to be swapped aggressively. Valid values are whole numbers between 0 and 100 . If the swappiness parameter isn't speci- fied, a default value of 60 is used. If a value isn't specified for maxSwap , then this parame- ter is ignored. If maxSwap is set to 0, the container doesn't use swap. This parameter maps to the --memory-swappiness option to docker run . Consider the following when you use a per-con- tainer swap configuration. o Swap space must be enabled and allocated on the container instance for the containers to use. NOTE: By default, the Amazon ECS optimized AMIs don't have swap enabled. You must enable swap on the instance to use this feature. For more information, see Instance store swap volumes in the Amazon EC2 User Guide for Linux Instances or How do I allocate memory to work as swap space in an Amazon EC2 instance by using a swap file? o The swap space parameters are only supported for job definitions using EC2 resources. o If the maxSwap and swappiness parameters are omitted from a job definition, each container has a default swappiness value of 60. More- over, the total swap usage is limited to two times the memory reservation of the con- tainer. NOTE: This parameter isn't applicable to jobs that are running on Fargate resources. Don't provide it for these jobs. logConfiguration -&gt; (structure) The log configuration specification for the con- tainer. This parameter maps to LogConfig in the Create a container section of the Docker Remote API and the --log-driver option to docker run . By default, containers use the same logging driver that the Docker daemon uses. However the container can use a different logging driver than the Docker daemon by specifying a log driver with this para- meter in the container definition. To use a dif- ferent logging driver for a container, the log system must be configured properly on the con- tainer instance (or on a different log server for remote logging options). For more information about the options for different supported log dri- vers, see Configure logging drivers in the Docker documentation . NOTE: Amazon ECS currently supports a subset of the logging drivers available to the Docker daemon (shown in the LogConfiguration data type). Ad- ditional log drivers may be available in future releases of the Amazon ECS container agent. This parameter requires version 1.18 of the Docker Remote API or greater on your container instance. To check the Docker Remote API version on your container instance, log in to your container in- stance and run the following command: sudo docker version --format '{{.Server.APIVersion}}' NOTE: The Amazon ECS container agent running on a container instance must register the logging drivers available on that instance with the ECS_AVAILABLE_LOGGING_DRIVERS environment vari- able before containers placed on that instance can use these log configuration options. For more information, see Amazon ECS container agent configuration in the Amazon Elastic Con- tainer Service Developer Guide . logDriver -&gt; (string) [required] The log driver to use for the container. The valid values that are listed for this parameter are log drivers that the Amazon ECS container agent can communicate with by default. The supported log drivers are awsfirelens , awslogs , fluentd , gelf , json-file , journald , logentries , syslog , and splunk . NOTE: Jobs that are running on Fargate resources are restricted to the awslogs and splunk log drivers. awsfirelens Specifies the firelens logging driver. For more information on configuring Firelens, see Send Amazon ECS logs to an Amazon Web Services ser- vice or Amazon Web Services Partner in the Ama- zon Elastic Container Service Developer Guide . awslogs Specifies the Amazon CloudWatch Logs logging driver. For more information, see Using the awslogs log driver in the Batch User Guide and Amazon CloudWatch Logs logging driver in the Docker documentation. fluentd Specifies the Fluentd logging driver. For more information including usage and options, see Fluentd logging driver in the Docker documenta- tion . gelf Specifies the Graylog Extended Format (GELF) logging driver. For more information including usage and options, see Graylog Extended Format logging driver in the Docker documentation . journald Specifies the journald logging driver. For more information including usage and options, see Journald logging driver in the Docker documen- tation . json-file Specifies the JSON file logging driver. For more information including usage and options, see JSON File logging driver in the Docker doc- umentation . splunk Specifies the Splunk logging driver. For more information including usage and options, see Splunk logging driver in the Docker documenta- tion . syslog Specifies the syslog logging driver. For more information including usage and options, see Syslog logging driver in the Docker documenta- tion . NOTE: If you have a custom driver that's not listed earlier that you want to work with the Amazon ECS container agent, you can fork the Amazon ECS container agent project that's available on GitHub and customize it to work with that driver. We encourage you to submit pull requests for changes that you want to have included. However, Amazon Web Services doesn't currently support run- ning modified copies of this software. This parameter requires version 1.18 of the Docker Remote API or greater on your container instance. To check the Docker Remote API ver- sion on your container instance, log in to your container instance and run the following com- mand: sudo docker version | grep "Server API version" Possible values: o json-file o syslog o journald o gelf o fluentd o awslogs o splunk o awsfirelens options -&gt; (map) The configuration options to send to the log driver. This parameter requires version 1.19 of the Docker Remote API or greater on your con- tainer instance. To check the Docker Remote API version on your container instance, log in to your container instance and run the following command: sudo docker version | grep "Server API version" key -&gt; (string) value -&gt; (string) secretOptions -&gt; (list) The secrets to pass to the log configuration. For more information, see Specifying sensitive data in the Batch User Guide . (structure) An object that represents the secret to ex- pose to your container. Secrets can be ex- posed to a container in the following ways: o To inject sensitive data into your con- tainers as environment variables, use the secrets container definition parameter. o To reference sensitive information in the log configuration of a container, use the secretOptions container definition para- meter. For more information, see Specifying sensi- tive data in the Batch User Guide . name -&gt; (string) [required] The name of the secret. valueFrom -&gt; (string) [required] The secret to expose to the container. The supported values are either the full Amazon Resource Name (ARN) of the Se- crets Manager secret or the full ARN of the parameter in the Amazon Web Services Systems Manager Parameter Store. NOTE: If the Amazon Web Services Systems Manager Parameter Store parameter exists in the same Region as the job you're launching, then you can use either the full Amazon Resource Name (ARN) or name of the parameter. If the parameter exists in a different Region, then the full ARN must be specified. mountPoints -&gt; (list) The mount points for data volumes in your con- tainer. This parameter maps to Volumes in the Create a container section of the Docker Remote API and the --volume option to `docker run . Windows containers can mount whole directories on the same drive as $env:ProgramData . Windows con- tainers can't mount directories on a different drive, and mount point can't be across drives. (structure) Details for a Docker volume mount point that's used in a job's container properties. This pa- rameter maps to Volumes in the Create a con- tainer section of the Docker Remote API and the --volume option to docker run. containerPath -&gt; (string) The path on the container where the host volume is mounted. readOnly -&gt; (boolean) If this value is true , the container has read-only access to the volume. Otherwise, the container can write to the volume. The default value is false . sourceVolume -&gt; (string) The name of the volume to mount. name -&gt; (string) The name of a container. The name can be used as a unique identifier to target your dependsOn and Overrides objects. privileged -&gt; (boolean) When this parameter is true , the container is given elevated privileges on the host container instance (similar to the root user). This parame- ter maps to Privileged in the Create a container section of the Docker Remote API and the --privi- leged option to docker run . NOTE: This parameter is not supported for Windows containers or tasks run on Fargate. readonlyRootFilesystem -&gt; (boolean) When this parameter is true, the container is given read-only access to its root file system. This parameter maps to ReadonlyRootfs in the Create a container section of the Docker Remote API and the --read-only option to docker run . NOTE: This parameter is not supported for Windows containers. repositoryCredentials -&gt; (structure) The private repository authentication credentials to use. credentialsParameter -&gt; (string) [required] The Amazon Resource Name (ARN) of the secret containing the private repository credentials. resourceRequirements -&gt; (list) The type and amount of a resource to assign to a container. The only supported resource is a GPU. (structure) The type and amount of a resource to assign to a container. The supported resources include GPU , MEMORY , and VCPU . value -&gt; (string) [required] The quantity of the specified resource to reserve for the container. The values vary based on the type specified. type="GPU" The number of physical GPUs to reserve for the container. Make sure that the number of GPUs reserved for all containers in a job doesn't exceed the number of available GPUs on the compute resource that the job is launched on. NOTE: GPUs aren't available for jobs that are running on Fargate resources. type="MEMORY" The memory hard limit (in MiB) present to the container. This parameter is supported for jobs that are running on Amazon EC2 re- sources. If your container attempts to ex- ceed the memory specified, the container is terminated. This parameter maps to Memory in the Create a container section of the Docker Remote API and the --memory option to docker run . You must specify at least 4 MiB of memory for a job. This is required but can be specified in several places for multi-node parallel (MNP) jobs. It must be specified for each node at least once. This parameter maps to Memory in the Create a container section of the Docker Remote API and the --memory option to docker run . NOTE: If you're trying to maximize your re- source utilization by providing your jobs as much memory as possible for a particular instance type, see Memory management in the Batch User Guide . For jobs that are running on Fargate re- sources, then value is the hard limit (in MiB), and must match one of the supported values and the VCPU values must be one of the values supported for that memory value. value = 512 VCPU = 0.25 value = 1024 VCPU = 0.25 or 0.5 value = 2048 VCPU = 0.25, 0.5, or 1 value = 3072 VCPU = 0.5, or 1 value = 4096 VCPU = 0.5, 1, or 2 value = 5120, 6144, or 7168 VCPU = 1 or 2 value = 8192 VCPU = 1, 2, or 4 value = 9216, 10240, 11264, 12288, 13312, 14336, or 15360 VCPU = 2 or 4 value = 16384 VCPU = 2, 4, or 8 value = 17408, 18432, 19456, 21504, 22528, 23552, 25600, 26624, 27648, 29696, or 30720 VCPU = 4 value = 20480, 24576, or 28672 VCPU = 4 or 8 value = 36864, 45056, or 53248 VCPU = 8 value = 61440 VCPU = 8 or 32 value = 32768, 40960, 49152, or 57344 VCPU = 8 or 16 value = 65536, 73728, 81920, 90112, 98304, 106496, or 114688 VCPU = 16 value = 122880 VCPU = 16 or 32 value = 249856 VCPU = 32 type="VCPU" The number of vCPUs reserved for the con- tainer. This parameter maps to CpuShares in the Create a container section of the Docker Remote API and the --cpu-shares op- tion to docker run . Each vCPU is equiva- lent to 1,024 CPU shares. For Amazon EC2 resources, you must specify at least one vCPU. This is required but can be specified in several places; it must be specified for each node at least once. The default for the Fargate On-Demand vCPU resource count quota is 6 vCPUs. For more information about Fargate quotas, see Fargate quotas in the Amazon Web Services General Reference . For jobs that are running on Fargate re- sources, then value must match one of the supported values and the MEMORY values must be one of the values supported for that VCPU value. The supported values are 0.25, 0.5, 1, 2, 4, 8, 16, and 32. value = 0.25 MEMORY = 512, 1024, or 2048 value = 0.5 MEMORY = 1024, 2048, 3072, or 4096 value = 1 MEMORY = 2048, 3072, 4096, 5120, 6144, 7168, or 8192 value = 2 MEMORY = 4096, 5120, 6144, 7168, 8192, 9216, 10240, 11264, 12288, 13312, 14336, 15360, or 16384 value = 4 MEMORY = 8192, 9216, 10240, 11264, 12288, 13312, 14336, 15360, 16384, 17408, 18432, 19456, 20480, 21504, 22528, 23552, 24576, 25600, 26624, 27648, 28672, 29696, or 30720 value = 8 MEMORY = 16384, 20480, 24576, 28672, 32768, 36864, 40960, 45056, 49152, 53248, 57344, or 61440 value = 16 MEMORY = 32768, 40960, 49152, 57344, 65536, 73728, 81920, 90112, 98304, 106496, 114688, or 122880 value = 32 MEMORY = 61440, 122880, or 249856 type -&gt; (string) [required] The type of resource to assign to a con- tainer. The supported resources include GPU , MEMORY , and VCPU . Possible values: o GPU o VCPU o MEMORY secrets -&gt; (list) The secrets to pass to the container. For more in- formation, see Specifying Sensitive Data in the Amazon Elastic Container Service Developer Guide. (structure) An object that represents the secret to expose to your container. Secrets can be exposed to a container in the following ways: o To inject sensitive data into your containers as environment variables, use the secrets container definition parameter. o To reference sensitive information in the log configuration of a container, use the secre- tOptions container definition parameter. For more information, see Specifying sensitive data in the Batch User Guide . name -&gt; (string) [required] The name of the secret. valueFrom -&gt; (string) [required] The secret to expose to the container. The supported values are either the full Amazon Resource Name (ARN) of the Secrets Manager secret or the full ARN of the parameter in the Amazon Web Services Systems Manager Pa- rameter Store. NOTE: If the Amazon Web Services Systems Man- ager Parameter Store parameter exists in the same Region as the job you're launching, then you can use either the full Amazon Resource Name (ARN) or name of the parameter. If the parameter ex- ists in a different Region, then the full ARN must be specified. ulimits -&gt; (list) A list of ulimits to set in the container. If a ulimit value is specified in a task definition, it overrides the default values set by Docker. This parameter maps to Ulimits in the Create a con- tainer section of the Docker Remote API and the --ulimit option to docker run . Amazon ECS tasks hosted on Fargate use the default resource limit values set by the operating system with the exception of the nofile resource limit parameter which Fargate overrides. The nofile re- source limit sets a restriction on the number of open files that a container can use. The default nofile soft limit is 1024 and the default hard limit is 65535 . This parameter requires version 1.18 of the Docker Remote API or greater on your container instance. To check the Docker Remote API version on your container instance, log in to your container in- stance and run the following command: sudo docker version --format '{{.Server.APIVersion}}' NOTE: This parameter is not supported for Windows containers. (structure) The ulimit settings to pass to the container. For more information, see Ulimit . NOTE: This object isn't applicable to jobs that are running on Fargate resources. hardLimit -&gt; (integer) [required] The hard limit for the ulimit type. name -&gt; (string) [required] The type of the ulimit . Valid values are: core | cpu | data | fsize | locks | memlock | msgqueue | nice | nofile | nproc | rss | rtprio | rttime | sigpending | stack . softLimit -&gt; (integer) [required] The soft limit for the ulimit type. user -&gt; (string) The user to use inside the container. This parame- ter maps to User in the Create a container section of the Docker Remote API and the --user option to docker run. NOTE: When running tasks using the host network mode, don't run containers using the root user (UID 0) . We recommend using a non-root user for better security. You can specify the user using the following for- mats. If specifying a UID or GID, you must specify it as a positive integer. o user o user:group o uid o uid:gid o user:gi o uid:group NOTE: This parameter is not supported for Windows containers. startTimeout -&gt; (integer) Time duration (in seconds) to wait before giving up on resolving dependencies for a container. The minimum value is 2 seconds and the maximum value for Fargate is 120 seconds. stopTimeout -&gt; (integer) Time duration (in seconds) to wait before the con- tainer is forcefully killed if it doesn't exit normally on its own. The minimum value is 2 sec- onds and the maximum value for Fargate is 120 sec- onds. If the parameter is not specified, the de- fault value of 30 seconds is used. For tasks that use the EC2 launch type, if the stopTimeout para- meter isn't specified, the value set for the Ama- zon ECS container agent configuration variable ECS_CONTAINER_STOP_TIMEOUT is used. If neither the stopTimeout parameter nor the ECS_CON- TAINER_STOP_TIMEOUT agent configuration variable are set, then the default value of 30 seconds is used. ephemeralStorage -&gt; (structure) The amount of ephemeral storage to allocate for the task. This parameter is used to expand the total amount of ephemeral storage available, beyond the default amount, for tasks hosted on Fargate. sizeInGiB -&gt; (integer) [required] The total amount, in GiB, of ephemeral storage to set for the task. The minimum supported value is 21 GiB and the maximum supported value is 200 GiB. executionRoleArn -&gt; (string) The Amazon Resource Name (ARN) of the execution role that Batch can assume. For jobs that run on Fargate resources, you must provide an execution role. For more information, see Batch execution IAM role in the Batch User Guide . platformVersion -&gt; (string) The Fargate platform version where the jobs are running. A platform version is specified only for jobs that are running on Fargate resources. If one isn't specified, the LATEST platform version is used by default. This uses a recent, approved version of the Fargate platform for com- pute resources. For more information, see Fargate plat- form versions in the Amazon Elastic Container Service De- veloper Guide . ipcMode -&gt; (string) The IPC resource namespace to use for the containers in the task. The valid values are host , task , or none . If host is specified, all containers within the tasks that specified the host IPC mode on the same container instance share the same IPC resources with the host Ama- zon EC2 instance. If task is specified, all containers within the specified task share the same IPC resources. If none is specified, the IPC resources within the con- tainers of a task are private, and are not shared with other containers in a task or on the container instance. If no value is specified, then the IPC resource namespace sharing depends on the Docker daemon setting on the con- tainer instance. For more information, see IPC settings in the Docker run reference. NOTE: This parameter is not supported for jobs that run on Fargate resources. taskRoleArn -&gt; (string) The Amazon Resource Name (ARN) that's associated with the Amazon ECS task. NOTE: This is object is comparable to ContainerProperties:jobRoleArn . pidMode -&gt; (string) The process namespace to use for the containers in the task. The valid values are host or task . For example, monitoring sidecars might need pidMode to access informa- tion about other containers running in the same task. If host is specified, all containers within the tasks that specified the host PID mode on the same container instance share the process namespace with the host Amazon EC2 instance. If task is specified, all containers within the specified task share the same process namespace. If no value is specified, the default is a private name- space for each container. For more information, see PID settings in the Docker run reference. networkConfiguration -&gt; (structure) The network configuration for jobs that are running on Fargate resources. Jobs that are running on Amazon EC2 resources or Amazon ECS Managed Instances must not spec- ify this parameter. assignPublicIp -&gt; (string) Indicates whether the job has a public IP address. For a job that's running on Fargate resources in a private subnet to send outbound traffic to the internet (for example, to pull container images), the private subnet requires a NAT gateway be attached to route requests to the internet. For more information, see Amazon ECS task networking in the Amazon Elastic Container Ser- vice Developer Guide . The default value is "DISABLED ". Possible values: o ENABLED o DISABLED runtimePlatform -&gt; (structure) An object that represents the compute environment archi- tecture for Batch jobs on Fargate or Amazon ECS Managed Instances. Use this to specify the operating system fam- ily (operatingSystemFamily ) and CPU architecture (cpuAr- chitecture ). For Amazon ECS Managed Instances, the valid value for op- eratingSystemFamily is LINUX (default). The valid values for cpuArchitecture are X86_64 and ARM64 . operatingSystemFamily -&gt; (string) The operating system for the compute environment. Valid values are: LINUX (default), WIN- DOWS_SERVER_2019_CORE , WINDOWS_SERVER_2019_FULL , WINDOWS_SERVER_2022_CORE , and WIN- DOWS_SERVER_2022_FULL . NOTE: The following parameters cant be set for Windows containers: linuxParameters , privileged , user , ulimits , readonlyRootFilesystem , and efsVolume- Configuration . NOTE: The Batch Scheduler checks the compute environ- ments that are attached to the job queue before registering a task definition with Fargate. In this scenario, the job queue is where the job is submitted. If the job requires a Windows container and the first compute environment is LINUX , the compute environment is skipped and the next com- pute environment is checked until a Windows-based compute environment is found. NOTE: Fargate Spot is not supported on Windows-based containers on Fargate. A job queue will be blocked if a Windows job is submitted to a job queue with only Fargate Spot compute environments. However, you can attach both FARGATE and FARGATE_SPOT com- pute environments to the same job queue. cpuArchitecture -&gt; (string) The vCPU architecture. The default value is X86_64 . Valid values are X86_64 and ARM64 . NOTE: This parameter must be set to X86_64 for Windows containers. NOTE: Fargate Spot is not supported on Windows-based containers on Fargate. A job queue will be blocked if a Windows job is submitted to a job queue with only Fargate Spot compute environments. However, you can attach both FARGATE and FARGATE_SPOT com- pute environments to the same job queue. volumes -&gt; (list) A list of volumes that are associated with the job. (structure) A data volume that's used in a job's container proper- ties. host -&gt; (structure) The contents of the host parameter determine whether your data volume persists on the host con- tainer instance and where it's stored. If the host parameter is empty, then the Docker daemon assigns a host path for your data volume. However, the data isn't guaranteed to persist after the con- tainers that are associated with it stop running. NOTE: This parameter isn't applicable to jobs that are running on Fargate resources and shouldn't be provided. sourcePath -&gt; (string) The path on the host container instance that's presented to the container. If this parameter is empty, then the Docker daemon has assigned a host path for you. If this parameter contains a file location, then the data volume persists at the specified location on the host container instance until you delete it manually. If the source path location doesn't exist on the host container instance, the Docker daemon creates it. If the location does exist, the contents of the source path folder are exported. NOTE: This parameter isn't applicable to jobs that run on Fargate resources. Don't pro- vide this for these jobs. name -&gt; (string) The name of the volume. It can be up to 255 char- acters long. It can contain uppercase and lower- case letters, numbers, hyphens (-), and under- scores (_). This name is referenced in the sourceVolume parameter of container definition mountPoints . efsVolumeConfiguration -&gt; (structure) This parameter is specified when you're using an Amazon Elastic File System file system for job storage. Jobs that are running on Fargate re- sources must specify a platformVersion of at least 1.4.0 . fileSystemId -&gt; (string) [required] The Amazon EFS file system ID to use. rootDirectory -&gt; (string) The directory within the Amazon EFS file system to mount as the root directory inside the host. If this parameter is omitted, the root of the Amazon EFS volume is used instead. Specifying / has the same effect as omitting this parameter. The maximum length is 4,096 characters. WARNING: If an EFS access point is specified in the authorizationConfig , the root directory parameter must either be omitted or set to / , which enforces the path set on the Ama- zon EFS access point. transitEncryption -&gt; (string) Determines whether to enable encryption for Amazon EFS data in transit between the Amazon ECS host and the Amazon EFS server. Transit en- cryption must be enabled if Amazon EFS IAM au- thorization is used. If this parameter is omit- ted, the default value of DISABLED is used. For more information, see Encrypting data in tran- sit in the Amazon Elastic File System User Guide . Possible values: o ENABLED o DISABLED transitEncryptionPort -&gt; (integer) The port to use when sending encrypted data be- tween the Amazon ECS host and the Amazon EFS server. If you don't specify a transit encryp- tion port, it uses the port selection strategy that the Amazon EFS mount helper uses. The value must be between 0 and 65,535. For more information, see EFS mount helper in the Amazon Elastic File System User Guide . authorizationConfig -&gt; (structure) The authorization configuration details for the Amazon EFS file system. accessPointId -&gt; (string) The Amazon EFS access point ID to use. If an access point is specified, the root di- rectory value specified in the EFSVolume- Configuration must either be omitted or set to / which enforces the path set on the EFS access point. If an access point is used, transit encryption must be enabled in the EFSVolumeConfiguration . For more informa- tion, see Working with Amazon EFS access points in the Amazon Elastic File System User Guide . iam -&gt; (string) Whether or not to use the Batch job IAM role defined in a job definition when mounting the Amazon EFS file system. If en- abled, transit encryption must be enabled in the EFSVolumeConfiguration . If this pa- rameter is omitted, the default value of DISABLED is used. For more information, see Using Amazon EFS access points in the Batch User Guide . EFS IAM authorization requires that TransitEncryption be ENABLED and that a JobRoleArn is specified. Possible values: o ENABLED o DISABLED s3filesVolumeConfiguration -&gt; (structure) This parameter is specified when you're using an S3Files file system for job storage. fileSystemArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the S3Files file system to use. rootDirectory -&gt; (string) The directory within the S3Files file system to mount as the root directory. transitEncryptionPort -&gt; (integer) The port to use when sending encrypted data be- tween the Amazon ECS host and the S3Files file system server. accessPointArn -&gt; (string) The Amazon Resource Name (ARN) of the S3Files access point to use. enableExecuteCommand -&gt; (boolean) Determines whether execute command functionality is turned on for this task. If true , execute command func- tionality is turned on all the containers in the task. networkMode -&gt; (string) The network mode to use for the task. Valid values: host . When not specified, the default is host . With host mode, the container shares the host instance's network stack directly. When running tasks that use the host network mode, do not run containers using the root user (UID 0). Running as root grants unrestricted access to host resources and increases the attack surface. This parameter only applies to jobs running on Amazon ECS Managed Instances (MANAGED_INSTANCES platform capabil- ity). It cannot be specified for Fargate or Amazon EC2 platform job definitions. JSON Syntax: { "taskProperties": [ { "containers": [ { "command": ["string", ...], "dependsOn": [ { "containerName": "string", "condition": "string" } ... ], "environment": [ { "name": "string", "value": "string" } ... ], "essential": true|false, "firelensConfiguration": { "type": "fluentd"|"fluentbit", "options": {"string": "string" ...} }, "image": "string", "linuxParameters": { "devices": [ { "hostPath": "string", "containerPath": "string", "permissions": ["READ"|"WRITE"|"MKNOD", ...] } ... ], "initProcessEnabled": true|false, "sharedMemorySize": integer, "tmpfs": [ { "containerPath": "string", "size": integer, "mountOptions": ["string", ...] } ... ], "maxSwap": integer, "swappiness": integer }, "logConfiguration": { "logDriver": "json-file"|"syslog"|"journald"|"gelf"|"fluentd"|"awslogs"|"splunk"|"awsfirelens", "options": {"string": "string" ...}, "secretOptions": [ { "name": "string", "valueFrom": "string" } ... ] }, "mountPoints": [ { "containerPath": "string", "readOnly": true|false, "sourceVolume": "string" } ... ], "name": "string", "privileged": true|false, "readonlyRootFilesystem": true|false, "repositoryCredentials": { "credentialsParameter": "string" }, "resourceRequirements": [ { "value": "string", "type": "GPU"|"VCPU"|"MEMORY" } ... ], "secrets": [ { "name": "string", "valueFrom": "string" } ... ], "ulimits": [ { "hardLimit": integer, "name": "string", "softLimit": integer } ... ], "user": "string", "startTimeout": integer, "stopTimeout": integer } ... ], "ephemeralStorage": { "sizeInGiB": integer }, "executionRoleArn": "string", "platformVersion": "string", "ipcMode": "string", "taskRoleArn": "string", "pidMode": "string", "networkConfiguration": { "assignPublicIp": "ENABLED"|"DISABLED" }, "runtimePlatform": { "operatingSystemFamily": "string", "cpuArchitecture": "string" }, "volumes": [ { "host": { "sourcePath": "string" }, "name": "string", "efsVolumeConfiguration": { "fileSystemId": "string", "rootDirectory": "string", "transitEncryption": "ENABLED"|"DISABLED", "transitEncryptionPort": integer, "authorizationConfig": { "accessPointId": "string", "iam": "ENABLED"|"DISABLED" } }, "s3filesVolumeConfiguration": { "fileSystemArn": "string", "rootDirectory": "string", "transitEncryptionPort": integer, "accessPointArn": "string" } } ... ], "enableExecuteCommand": true|false, "networkMode": "string" } ... ] }
    /// </summary>
    [CliOption("--ecs-properties")]
    public string? EcsProperties { get; set; }

    /// <summary>
    /// Contains a list of consumable resources required by the job. consumableResourceList -&gt; (list) The list of consumable resources required by a job. (structure) Information about a consumable resource required to run a job. consumableResource -&gt; (string) The name or ARN of the consumable resource. quantity -&gt; (long) The quantity of the consumable resource that is needed. Shorthand Syntax: consumableResourceList=[{consumableResource=string,quantity=long},{consumableResource=string,quantity=long}] JSON Syntax: { "consumableResourceList": [ { "consumableResource": "string", "quantity": long } ... ] }
    /// </summary>
    [CliOption("--consumable-resource-properties")]
    public string? ConsumableResourceProperties { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

    }

}
